// Aeruvo service worker — app-shell caching + Firebase Cloud Messaging.
//
// App-shell: caches same-origin JS/CSS/fonts/images for instant repeat-visits
// and offline fallback. Never caches API responses (weather, geocoding).
//
// FCM: initialized from public/firebase-sw-config.js which is auto-generated
// at build time from VITE_FIREBASE_* env vars. The SW can start from zero
// (no client page open) and still initialize FCM — no postMessage required.

// ── Firebase SW config ───────────────────────────────────────────────────
//
// firebase-sw-config.js is generated by scripts/generate-sw-config.cjs
// (run automatically as `prebuild` and `predev` npm hooks).
// It sets self.AERUVO_FIREBASE_CONFIG from the same VITE_FIREBASE_* env vars
// used by the client bundle. Single source of truth, auto-generated, never
// hand-edited. If Firebase is not configured, it sets the value to null.
//
// WHY this approach (not postMessage):
//   Service workers are ephemeral — the browser terminates them when no pages
//   are open. A push event can wake a terminated SW from zero. If config only
//   arrived via postMessage from an open page, a cold-started SW would have
//   no config and could not display the notification. importScripts at module
//   startup runs synchronously before any push event handler, guaranteeing
//   config is available whenever the SW is alive.
try {
  importScripts("/firebase-sw-config.js");
} catch (e) {
  console.warn("[aeruvo:sw] could not load firebase-sw-config.js:", e && e.message);
}

// ── App-shell cache ───────────────────────────────────────────────────────

const CACHE_NAME = "aeruvo-shell-v1";
const STATIC_EXTENSIONS = [".js", ".css", ".woff2", ".woff", ".png", ".svg", ".ico", ".webmanifest"];

self.addEventListener("install", () => { self.skipWaiting(); });

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k))),
    ),
  );
  self.clients.claim();
});

function isStaticAsset(url) {
  return STATIC_EXTENSIONS.some((ext) => url.pathname.endsWith(ext));
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (isStaticAsset(url)) {
    event.respondWith(
      caches.open(CACHE_NAME).then(async (cache) => {
        const cached = await cache.match(request);
        const network = fetch(request)
          .then((res) => { if (res.ok) cache.put(request, res.clone()); return res; })
          .catch(() => cached);
        return cached || network;
      }),
    );
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request)
        .then((res) => {
          caches.open(CACHE_NAME).then((cache) => cache.put(request, res.clone()));
          return res;
        })
        .catch(() => caches.match(request).then((cached) => cached || caches.match("/"))),
    );
  }
});

// ── Firebase Cloud Messaging ──────────────────────────────────────────────
//
// REQUIRES: self.AERUVO_FIREBASE_CONFIG set by firebase-sw-config.js above.
// If null (Firebase not configured), FCM init is skipped gracefully.
//
// DATA-ONLY payload contract (Stage E must follow this):
//   The Cloud Function must send data-only FCM messages — no `notification`
//   field. This SW reads payload.data.title/body/url and calls
//   showNotification() manually. If a `notification` field is also present,
//   the browser auto-displays a notification AND this handler fires — two
//   notifications appear. Stage E Cloud Function must use data-only messages.

if (self.AERUVO_FIREBASE_CONFIG) {
  try {
    importScripts("https://www.gstatic.com/firebasejs/12.15.0/firebase-app-compat.js");
    importScripts("https://www.gstatic.com/firebasejs/12.15.0/firebase-messaging-compat.js");

    firebase.initializeApp(self.AERUVO_FIREBASE_CONFIG);
    const messaging = firebase.messaging();

    messaging.onBackgroundMessage((payload) => {
      const title = (payload.data && payload.data.title) || "Aeruvo";
      const body  = (payload.data && payload.data.body)  || "Check today's forecast.";
      const url   = (payload.data && payload.data.url)   || "/";

      self.registration.showNotification(title, {
        body,
        icon:  "/icon-192.png",
        badge: "/icon-96.png",
        tag:   "aeruvo-rain-reminder",  // collapses duplicate notifications
        data:  { url },
      });
    });
  } catch (e) {
    // FCM failure must never break app-shell caching or navigation.
    console.warn("[aeruvo:sw] FCM init failed:", e && e.message);
  }
}

// ── Notification click ────────────────────────────────────────────────────

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = (event.notification.data && event.notification.data.url) || "/";
  event.waitUntil(
    self.clients
      .matchAll({ type: "window", includeUncontrolled: true })
      .then((clients) => {
        const existing = clients.find((c) => new URL(c.url).origin === self.location.origin);
        if (existing) return existing.focus();
        return self.clients.openWindow(url);
      }),
  );
});
